import * as React from 'react';
import * as S from '@primasoftllc/design-system';
import '@primasoftllc/design-system/styles.css';

function LoadExample(props) {
    var retry = props.retry, state = React.useState('idle'), timer = React.useRef(null), pending = React.useRef(false), attempt = React.useRef(0);
    var loading = state[0] === 'loading', error = state[0] === 'error', done = state[0] === 'done';
    React.useEffect(function () { return function () { clearTimeout(timer.current); }; }, []);
    function load() {
        if (pending.current)
            return;
        pending.current = true;
        attempt.current++;
        state[1]('loading');
        timer.current = setTimeout(function () { pending.current = false; state[1](retry && attempt.current % 2 === 1 ? 'error' : 'done'); }, 1500);
    }
    var message = loading ? (retry ? 'Загрузка отчёта…' : 'Обновление отчёта…') : error ? 'Не удалось загрузить отчёт. Повторите попытку.' : done ? (retry ? 'Отчёт загружен.' : 'Отчёт обновлён.') : '';
    return <div className={"demo-stack"}>
    <div className={'toolbar'}>
    <S.DsButton variant={'secondary'} onClick={load} aria-disabled={loading}>
    {retry ? (error ? 'Повторить загрузку' : 'Загрузить отчёт') : 'Обновить отчёт'}
    </S.DsButton>
    </div>
    <div className={'result'}>
    <div className={'spinner-slot'} aria-hidden={'true'}>
    {loading ? <S.DsSpinner size={32}/> : null}
    </div>
    <div className={'data'} aria-busy={loading}>
    <p>
    {retry && !done ? 'Отчёт ещё не загружен.' : 'Отчёт: 24 объекта.'}
    </p>
    </div>
    </div>
    <p role={'status'} className={'message'}>
    {message}
    </p>
    </div>;
}
function App() {
    return <div className="dsspinner-example">
    <style>{exampleStyles}</style>
    <LoadExample />
    </div>;
}

const exampleStyles = ".dsspinner-example{font:var(--ds-type-body);color:var(--ds-fg)}\n.dsspinner-example .demo-stack{display:flex;flex-direction:column;gap:16px;min-width:0}\n.dsspinner-example p{margin:0}\n.dsspinner-example .toolbar{margin-bottom:16px}\n.dsspinner-example .result{display:flex;align-items:center;gap:12px;min-height:48px;overflow-wrap:anywhere}\n.dsspinner-example .spinner-slot{width:32px;height:32px;flex:none}\n.dsspinner-example .data{min-width:0;flex:1}\n.dsspinner-example .data p{margin:0}\n.dsspinner-example .data[aria-busy=\"true\"]{color:var(--ds-fg-muted)}\n.dsspinner-example .message{font:var(--ds-type-caption);color:var(--ds-fg-muted);min-height:36px;margin:8px 0 0;overflow-wrap:anywhere}";

export { App as Example };

